SELECT 
FROM llm_model

  AND type = #{type}
  AND enabled = #{enabled}

ORDER BY type ASC, is_default DESC, name ASC, id ASC

SELECT 
FROM llm_model WHERE id = #{id}
FOR UPDATE

SELECT EXISTS (
  SELECT 1 FROM llm_model WHERE name = #{name}
  AND id != #{excludeId}
)

SELECT EXISTS (
  SELECT 1 FROM llm_model WHERE type = #{type} AND is_default = true
  AND id != #{excludeId}
)

